with expected as (select date_trunc('month', reporting_date)::date as reporting_month, campaign_id, campaign_name, marketing_channel, sum(spend_gbp) as spend_gbp, sum(eligible_conversions) as eligible_conversions, sum(attributed_gross_merchandise_revenue_gbp) as attributed_gross_merchandise_revenue_gbp, sum(attributed_net_revenue_gbp) as attributed_net_revenue_gbp from {{ ref('mart_marketing__campaign_daily') }} group by 1,2,3,4), actual as (select reporting_month, campaign_id, campaign_name, marketing_channel, spend_gbp, eligible_conversions, attributed_gross_merchandise_revenue_gbp, attributed_net_revenue_gbp from {{ ref('mart_marketing__campaign_monthly') }}) select * from ((select * from expected except select * from actual) union all (select * from actual except select * from expected)) differences
union all select reporting_month, campaign_id, campaign_name, marketing_channel, spend_gbp, eligible_conversions, attributed_gross_merchandise_revenue_gbp, attributed_net_revenue_gbp from {{ ref('mart_marketing__campaign_monthly') }} where net_roas is distinct from attributed_net_revenue_gbp / nullif(spend_gbp, 0)
